$_MODULE['<{lggooglereviews}prestashop>help_21b295c24b7e059595f2393eee97eb8e'] = 'Sie können auswählen, welche Artikel Sie im öffentlichen Bereich Ihres Geschäfts anzeigen möchten und wie Sie dies tun möchten. Gehen Sie dazu auf die Registerkarte \"Präsentation\" Ihres Geschäfts:';
$_MODULE['<{lggooglereviews}prestashop>help_3612879708f67ddbaffef6b85b8a7721'] = 'Im Feld \"Anzuzeigende Bewertungen\" können Sie die Anzahl der Blöcke auswählen, die gleichzeitig im Schieberegler angezeigt werden sollen';
$_MODULE['<{lggooglereviews}prestashop>help_a8a22f09149459a347b30e8005ab34f4'] = '\"Rich Snippets\" sind eine Reihe von Tags, die für Ihre Kunden nicht sichtbar sind, aber von Suchmaschinen verwendet werden, um Informationen aus ihren Meinungen zu sammeln. Wenn Sie es den Suchmaschinen erleichtern möchten, diese Informationen zu erhalten, markieren Sie \"Ja\".';
$_MODULE['<{lggooglereviews}prestashop>help_dee2ff8dd3e1feec8bb332b79163a1a4'] = '\"Kopfzeile anzeigen\" fügt am Anfang des Blocks eine Kopfzeile ein, in der Sie Ihre Unternehmensdaten anzeigen können, wie z.B.: den Namen, das Bild, die Bewertungen und die Links zu Ihrem Profil in Google Places';
$_MODULE['<{lggooglereviews}prestashop>help_554d5ff6ac027319ca16bf76c83c6095'] = '\"Kopfzeilenbild anzeigen\" enthält das mit Ihrem Unternehmen verbundene Bild, wenn Sie es hochgeladen haben, und wenn nicht, das Standardsymbol, das Sie in Google My Business definiert haben.';
$_MODULE['<{lggooglereviews}prestashop>help_bc1b4b599ba23e1aaeda1e0d4de99c3b'] = '\"Link zur Google My Business-Seite Ihres Unternehmens anzeigen\" zeigt einen Link zu Ihrem Unternehmensprofil bei Google My Business an.';
$_MODULE['<{lggooglereviews}prestashop>help_ee27a2fa1a14965f274765a67e5a8924'] = '\"Link zu [Alle Bewertungen anzeigen]\" zeigt einen Link an, über den Ihre Kunden auf die vollständige Liste Ihrer Bewertungen auf Google My Business zugreifen können.';
$_MODULE['<{lggooglereviews}prestashop>help_559358899352d23a924ba8782fd364dc'] = '\"Link zu [Bewertung hinzufügen] anzeigen\" zeigt einen Link an, der Ihre Kunden dazu einlädt, eine Bewertung über Ihr Unternehmen abzugeben.';
$_MODULE['<{lggooglereviews}prestashop>help_1ef8624b78f3fd5b154773974b2f2dac'] = 'Wenn Sie die vorherige Option gewählt haben, müssen Sie die Einladungsurl angeben. Im Abschnitt \"Bewertungen anfordern\" der Hilfe erklären wir, wie Sie diese erhalten';
$_MODULE['<{lggooglereviews}prestashop>help_85cd03234f067e40d64fe6c28797fa67'] = 'Geben Sie an, ob Sie die Meldung \"Powered by Google\" anzeigen möchten.';
$_MODULE['<{lggooglereviews}prestashop>help_1628dd7f0d2519316c69e4e7700b9b2f'] = 'Geben Sie an, ob Sie Ihre Bewertung auf Google my Business anzeigen möchten';
$_MODULE['<{lggooglereviews}prestashop>help_3203e573a77f0fd7c5948c3d846abc52'] = 'Geben Sie an, ob Sie die Anzahl der in Google my Business erhaltenen Bewertungen anzeigen möchten';
$_MODULE['<{lggooglereviews}prestashop>help_bfd47e79bf08ab639511bf993139b22e'] = 'Wenn Sie die Liste der zuletzt erhaltenen Bewertungen anzeigen möchten, wählen Sie die Option';
$_MODULE['<{lggooglereviews}prestashop>help_a481969fefacd2cac4651bc0cad8ace8'] = 'Geben Sie an, ob Sie einen Link zum Profil von Nutzern anzeigen möchten, die ihre Bewertungen abgegeben haben';
$_MODULE['<{lggooglereviews}prestashop>help_4e7c6bc487018fc97dc555c507a10cc0'] = 'Überprüfen Sie Ihre Geschäftsdaten';
$_MODULE['<{lggooglereviews}prestashop>help_367c548945a796b5e52169e33b27202b'] = 'In der Registerkarte \"Statistiken\" sehen Sie eine statistische Zusammenfassung Ihrer Unternehmensdaten in Google My Business';
$_MODULE['<{lggooglereviews}prestashop>help_b1e986d1a578a5ff89bedf9d5e52b012'] = 'Um Google Maps und Places APIs zu nutzen, müssen Sie die Anwendung registrieren und einen API-Schlüssel erhalten. Wahrscheinlich wissen Sie das bereits, aber wir erklären Ihnen, wie Sie diesen Schlüssel erhalten, falls Sie das nicht wissen.';
$_MODULE['<{lggooglereviews}prestashop>help_929457b0d047a741db5a051fb3409dab'] = 'So erstellen Sie Ihren Google Maps API KEY';
$_MODULE['<{lggooglereviews}prestashop>help_9620b9481e88199f573c9800e8f2a621'] = 'Folgen Sie den nachstehenden Anweisungen, um einen API-Schlüssel zu erstellen.';
$_MODULE['<{lggooglereviews}prestashop>help_45887556e1cc6a572c574708e1676ea6'] = 'Sie müssen sich mit Ihrem gmail-Konto anmelden oder ein neues gmail-Konto erstellen, das Sie mit Ihrem Projekt verknüpfen möchten.';
$_MODULE['<{lggooglereviews}prestashop>help_b4c1815fa181e8d36cba075fb5ea51b8'] = 'Sobald Sie eingeloggt sind, sollten Sie die Google Cloud Platform-Konsole aufrufen:';
$_MODULE['<{lggooglereviews}prestashop>help_6b05e59b1c6f2513ea4ec8811602146c'] = 'Im Menü auf der linken Seite gelangen Sie zum Abschnitt APIS und Dienste.';
$_MODULE['<{lggooglereviews}prestashop>help_7622adcc5af6e55d3a7667c19c13a6fb'] = 'Geben Sie den Namen des Projekts ein und klicken Sie auf die Schaltfläche \"CREATE\".';
$_MODULE['<{lggooglereviews}prestashop>help_55fd75e5be5f25af27c8e67eb2faa100'] = 'Anschließend klicken wir auf die Schaltfläche \"APIS UND DIENSTE AKTIVIEREN\".';
$_MODULE['<{lggooglereviews}prestashop>help_fc45981f4bf623a93720e128bc1a1c10'] = 'In diesem Fall wählen Sie \"API PLACES\".';
$_MODULE['<{lggooglereviews}prestashop>help_7684dbca91a174e239e2a8d062df29b1'] = 'Klicken Sie auf die Schaltfläche \"AKTIVIEREN\".';
$_MODULE['<{lggooglereviews}prestashop>help_824a6c6060cae1ce4265e018736337df'] = 'Sobald die API erstellt ist, gehen Sie auf die Registerkarte \"Berechtigungsnachweise\". Klicken Sie dort auf den Link \"Berechtigungsnachweise in APIs und Diensten\".';
$_MODULE['<{lggooglereviews}prestashop>help_04ee3b1cdc9f4b27e27ec84255924905'] = 'Kopieren Sie den API-Schlüssel, der auf dem Bildschirm angezeigt wird, da wir ihn später benötigen.';
$_MODULE['<{lggooglereviews}prestashop>help_ebc72db384475b19cabb579e57785996'] = 'In demselben Pop-up-Fenster finden Sie die Option \"Passwort einschränken\". Klicken Sie auf diesen Link, wenn Sie möchten, dass der Schlüssel z. B. nur in einem bestimmten Bereich verwendet werden kann.';
$_MODULE['<{lggooglereviews}prestashop>help_449abc375ecc691847413fbc9d739a59'] = 'Sobald Sie das Passwort eingeschränkt haben, müssen wir, wenn Sie es wünschen, die Rechnungsdaten eingeben, da wir diese API sonst nur einmal pro Tag aufrufen dürfen, und ich hoffe sehr, dass Ihre Website mehr als einen Besuch pro Tag hat. Das bedeutet nicht, dass uns etwas in Rechnung gestellt wird, denn Google bietet Ihnen diesen Dienst für eine große Anzahl von Aufrufen der API kostenlos an, eine Anzahl, für die ein KMU-Unternehmen normalerweise nicht zahlen muss. Wenn Sie die Zahl der Aufrufe, die Google Ihnen kostenlos zur Verfügung stellt, überschreiten, ist es wahrscheinlich, dass das Geschäft sehr, sehr gut läuft und dass Sie kein Problem damit haben sollten, ein wenig in diese Sache zu investieren. Selbst wenn Sie nicht darüber hinausgehen, bittet Google Sie um Ihre Rechnungsdaten, falls das irgendwann einmal passiert. Zu Ihrer Beruhigung kann ich Ihnen aber sagen, dass Google Ihnen erlaubt, die Anzahl der Aufrufe seiner API pro Monat zu begrenzen. Sie können also die Anzahl der kostenlosen Anrufe pro Monat begrenzen, so dass Ihnen nie etwas berechnet wird; es werden lediglich die Meinungen eingestellt, wenn Sie diese Anzahl überschreiten.';
$_MODULE['<{lggooglereviews}prestashop>help_fb9ad09694f5986566d455aca68450a9'] = 'Wie gebe ich die Rechnungsdaten ein?';
$_MODULE['<{lggooglereviews}prestashop>help_719545827e174b52f5007290935e39e1'] = 'Folgen Sie den nachstehenden Anweisungen, um Ihre Rechnungsdaten einzugeben.';
$_MODULE['<{lggooglereviews}prestashop>help_78a42223fc0bf73ebd95dea4c186874f'] = 'Wenn Sie in der Google Cloud Platform-Konsole auf das Menüsymbol mit den drei horizontalen Linien ganz links klicken, wird das Navigationsmenü angezeigt. Dort müssen wir auf den Punkt \"Billing\" klicken.';
$_MODULE['<{lggooglereviews}prestashop>help_17bdf9283a5ae0b5df854db1dd3dd7c9'] = 'Wir klicken auf die Schaltfläche \"Rechnungskonten verwalten\".';
$_MODULE['<{lggooglereviews}prestashop>help_d854108423e34b73cf5b3537c4e74e69'] = 'Wir klicken auf die Schaltfläche \"Abrechnungskonto hinzufügen\" und befolgen die von Google angegebenen Schritte, indem wir die angeforderten Informationen eingeben.';
$_MODULE['<{lggooglereviews}prestashop>help_b04a7d3f4f74a068e64d49e24b110c76'] = 'Wählen Sie das Google-Zahlungsprofil, das mit diesem Abrechnungskonto verknüpft werden soll. Sie können ein bestehendes Profil auswählen oder ein neues erstellen.';
$_MODULE['<{lggooglereviews}prestashop>help_a800cf67d7ea062c818c5e9ee0f661a2'] = 'Schließlich müssen wir in dem Projekt, das Sie konfigurieren, die Rechnungsstellung für dieses Projekt aktivieren. Dies geschieht unter \"Abrechnung\", indem Sie auf \"Abrechnungskonto verknüpfen\" klicken. Wir wählen das Konto aus und klicken auf \"Konto einrichten\".';
$_MODULE['<{lggooglereviews}prestashop>help_1671ed90c633e5d528f47c66a166ed88'] = 'Woher weiß ich, wie die Ortskennung meines Unternehmens lautet?';
$_MODULE['<{lggooglereviews}prestashop>help_dc6d24a4104249b69c2e5c9aa5219d6e'] = 'Sie können auf diese Seite gehen';
$_MODULE['<{lggooglereviews}prestashop>help_cfff697597811556e2781f9146b228d3'] = 'Sie müssen nur den Namen Ihres Unternehmens eingeben, wie er in Google My Business erscheint, und es wird Ihnen Ihre PLACE ID angezeigt.';
$_MODULE['<{lggooglereviews}prestashop>help_0bd619dcb1b97765da7df00297813025'] = 'Kopieren Sie Ihre Google Place ID in Ihr Modul';
$_MODULE['<{lggooglereviews}prestashop>help_41b7f207a5bb87bc9b1c260f1723ff84'] = 'Wo finden Sie Ihre Url für die Anforderung von Bewertungen?';
$_MODULE['<{lggooglereviews}prestashop>help_68687ec484228e020f49b0e928ed12a8'] = 'Melden Sie sich bei Ihrem Google My Business-Konto an.';
$_MODULE['<{lggooglereviews}prestashop>help_ef1ea00aa6058bfdb2d98c7b4e75f98f'] = 'Wenn Sie mehr als ein Unternehmen in Ihrer Liste haben, wählen Sie das Unternehmen aus, das Sie auf Ihrer Website anzeigen möchten.';
$_MODULE['<{lggooglereviews}prestashop>help_f343afb0d26a2f95f77a42d91c826a74'] = 'Klicken Sie auf die Schaltfläche \"Profil teilen\".';
$_MODULE['<{lggooglereviews}prestashop>help_9ee9d25e1ced67fbd20cf2044e8279a7'] = 'Sie können die Kurz-URL direkt kopieren, damit Ihre Kunden ihre Bewertungen schreiben können.';
$_MODULE['<{lggooglereviews}prestashop>help_8d24d9fde106dfde17d8c8ffd71427a0'] = 'Markieren Sie in Ihrem Modul die Option \"Link zum Hinzufügen einer Bewertung anzeigen\" mit \"Ja\".';
$_MODULE['<{lggooglereviews}prestashop>help_45a492bc2c73886bfda54bd3d90013af'] = 'Fügen Sie die kopierte Url in das Feld \"Url to add reviews\" ein.';
$_MODULE['<{lggooglereviews}prestashop>help_24acebeaacbe556b1c6b2455ace449a0'] = 'Klicken Sie auf \"Speichern\".';
$_MODULE['<{lggooglereviews}prestashop>help_a0c66f7c856f2f3ddba66b75606ccdad'] = 'Dies sind einige der Fragen, die wir häufig sehen:';
$_MODULE['<{lggooglereviews}prestashop>help_a86756485fe7020269c81ba1b69811e5'] = 'Wenn der von Ihnen angelegte Ort als NICHT validiert erscheint, müssen folgende Prüfungen durchgeführt werden';
$_MODULE['<{lggooglereviews}prestashop>help_6ed1bbbbc54c2b62ade264c019167de6'] = 'Ohne die Eingabe der Rechnungsdaten wird das Modul nicht funktionieren.';
