$_MODULE['<{lggooglereviews}prestashop>help_78b820bd28c37829982ec1d5b45aeb27'] = 'In Google My Business müssen Sie eine Adresse für Ihr Unternehmen haben (auch wenn Sie ein 100%iger Online-Shop sind).';
